div.t-attf-style:
width: {{spec['width']}}%;
height: {{spec['height']}}px;
border: 1px solid black;
padding: 6px;
margin: 5px;
float: left;
box-sizing: border-box;
page-break-inside: avoid;
overflow: hidden;
display: flex;
flex-direction: column;
justify-content: space-between;
align-items: center;
text-align: center;

font-size: {{spec['title_fs']}}px;
font-weight: bold;
line-height: 1.1;
max-height: {{spec['title_fs'] * 1.6}}px;
overflow: hidden;
word-wrap: break-word;
white-space: normal;
width: 100%;
text-align: left;
